			PackedCostEstimate estimate = fixture.cost(algorithm);
			assertEquals(semantic == Semantic.EXISTS ? 0.0d : 2.0d, estimate.outputRows());
			assertEquals(0.0d, estimate.hashBuildRows());
			assertTrue(Double.isFinite(estimate.workRows()));
