	@Test
	void globalLimitMinusDeclinesTypedProbesAndRetainsIndependentLimit(@TempDir Path dataDirectory) {
		BindingSetAssignment left = finiteValues("first", "second", "third");
		Slice right = new Slice(finiteValues("first", "second", "third"), 0L, 1L);
		var call = PackedCostTestSupport.difference(left, right);
		for (int relation = 1; relation <= call.query().relationCount(); relation++) {
			assertFalse(call.query().isAntiJoin(relation)
					&& call.query().semiAntiKind(relation) == PackedQueryView.SEMI_ANTI_MINUS_ASSURED_SHARED,
					"global LIMIT must not become a per-left-row correlated MINUS probe");
		}
		Difference difference = assertInstanceOf(Difference.class,
				call.query().materializeRelation(call.differenceRelationId()));
		Slice independentRight = assertInstanceOf(Slice.class, difference.getRightArg());
		assertEquals(1L, independentRight.getLimit());

		LmdbStore store = new LmdbStore(dataDirectory.toFile());
		store.init();
		try (NotifyingSailConnection connection = store.getConnection()) {
			List<BindingSet> actual = new ArrayList<>();
			try (CloseableIteration<? extends BindingSet> rows = connection.evaluate(difference, null,
					EmptyBindingSet.getInstance(), false)) {
				while (rows.hasNext()) {
					actual.add(rows.next());
				}
			}
			assertEquals(2, actual.size(), "only the first independent RHS binding is removed from the outer bag");
			for (BindingSet expected : finiteValues("second", "third").getBindingSets()) {
				assertTrue(actual.contains(expected), "both remaining outer bindings must survive global LIMIT MINUS");
			}
		} finally {
			store.shutDown();
		}
	}

	private static BindingSetAssignment finiteValues(String... names) {
		List<BindingSet> rows = new ArrayList<>(names.length);
		for (String name : names) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("node", SimpleValueFactory.getInstance().createIRI("urn:semi-anti-cost:" + name));
			rows.add(row);
		}
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(rows);
		return values;
	}

